import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { m17DecodeLsf, m17DecodeStream, m17SoftBits, m17SyncSymbols, m17UnpackLsf, M17_SYNC } from '@/worker/decoders/dsd/m17/protocol';
import { M17Receiver } from '@/worker/decoders/dsd/m17/receiver';

// Generated by OnAir m17_proto.cpp at 3d3f1ca: LSF and stream symbols plus packed LSF.
const [lsfLine, streamLine, packedLine] = readFileSync(new URL('./m17-onair-fixture.txt', import.meta.url), 'utf8')
	.trim()
	.split(/\r?\n/);
const lsfSymbols = Int8Array.from(lsfLine.split(',').map(Number));
const streamSymbols = Int8Array.from(streamLine.split(',').map(Number));
const packed = Uint8Array.from(packedLine.match(/../g).map((pair) => parseInt(pair, 16)));

describe('M17 OnAir interoperability', () => {
	it('decodes the link setup frame with a checked CRC', () => {
		expect(Array.from(lsfSymbols.slice(0, 8))).toEqual(Array.from(m17SyncSymbols(M17_SYNC.lsf)));
		const decoded = m17DecodeLsf(m17SoftBits(lsfSymbols.slice(8)));
		expect(decoded.corrected).toBe(0);
		expect(decoded.lsf).toEqual(m17UnpackLsf(packed));
		expect(decoded.lsf).toMatchObject({ src: 'N0CALL', dst: '@ALL', type: 0x85 });
	});

	it('decodes the stream LICH, frame number and Codec2 payload', () => {
		expect(Array.from(streamSymbols.slice(0, 8))).toEqual(Array.from(m17SyncSymbols(M17_SYNC.stream)));
		const decoded = m17DecodeStream(m17SoftBits(streamSymbols.slice(8)));
		expect(decoded.lichValid).toBe(true);
		expect(decoded.golayErrors).toBe(0);
		expect(decoded.corrected).toBe(0);
		expect(decoded.frameNumber).toBe(0x1234);
		expect(Array.from(decoded.payload)).toEqual(Array.from({ length: 16 }, (_, index) => index));
	});

	it('rejects an LSF with a failed CRC', () => {
		const broken = packed.slice();
		broken[0] ^= 1;
		expect(m17UnpackLsf(broken)).toBeNull();
	});

	it('acquires the OnAir LSF and plays the next stream payload only when clear', () => {
		const frames = [];
		const receiver = new M17Receiver((frame) => frames.push(frame));
		for (const symbol of lsfSymbols) receiver.feed(symbol * 800);
		for (const symbol of streamSymbols) receiver.feed(symbol * 800);
		expect(frames).toHaveLength(2);
		expect(frames[0].status).toMatchObject({ src: 'N0CALL', dst: '@ALL', can: 1, kind: 'Voice 3200', encrypted: false });
		expect(frames[1].voice).toMatchObject({ rate: 3200, frameNumber: 0x1234 });
	});
});
